-- addon/tests/palette_spec.lua
-- The addon has one palette: addon/ForeverSixty/Tokens.lua, generated by design/tokens/build.mjs
-- from design/tokens/tokens.json, the site's one source (brand audit 2026-11-10, BA1). Theme.HEX is a
-- map onto it, and no other file names a colour: not a six-digit hex string, not a |cff escape with
-- digits in it, not a number handed to a colour setter. A colour the addon needs is a token first.
-- The same files keep the site's sentence case: no label in Locale.lua is written in capitals.
local ROOT = "ForeverSixty/"

--- Every shipped Lua file but the generated ones: Tokens.lua itself, and Data.lua (item data whose
--- quality numbers are not colours).
local GENERATED = { ["Tokens.lua"] = true, ["Data.lua"] = true }

local function shippedFiles()
	local files = {}
	local list = io.popen('find "' .. ROOT .. '" -name "*.lua"')
	for path in list:lines() do
		local name = path:sub(#ROOT + 1)
		if not GENERATED[name] then
			files[#files + 1] = path
		end
	end
	list:close()
	table.sort(files)
	return files
end

--- A line's code, without its comment (a `--` outside a string), which may quote a colour.
local function code(line)
	local inString, quote = false, nil
	local index = 1
	while index <= #line do
		local char = line:sub(index, index)
		if inString then
			if char == "\\" then
				index = index + 1
			elseif char == quote then
				inString = false
			end
		elseif char == '"' or char == "'" then
			inString, quote = true, char
		elseif line:sub(index, index + 1) == "--" then
			return line:sub(1, index - 1)
		end
		index = index + 1
	end
	return line
end

local LITERALS = {
	{ pattern = "[\"']%x%x%x%x%x%x[\"']", what = "a hex colour" },
	{ pattern = "|c[fF][fF]%x%x%x%x%x%x", what = "a |cff colour escape" },
	{ pattern = "Set%a*Color%a*%(%s*[%d%.]", what = "a number handed to a colour setter" },
	{ pattern = "SetColorTexture%(%s*[%d%.]", what = "a number handed to SetColorTexture" },
	{ pattern = "CreateColor%(%s*[%d%.]", what = "a number handed to CreateColor" },
}

describe("the palette", function()
	it("names no colour outside Tokens.lua", function()
		local found = {}
		for _, path in ipairs(shippedFiles()) do
			local number = 0
			for line in io.lines(path) do
				number = number + 1
				local body = code(line)
				for _, literal in ipairs(LITERALS) do
					if body:find(literal.pattern) then
						found[#found + 1] = string.format("%s:%d: %s", path, number, literal.what)
					end
				end
			end
		end
		assert.are.same({}, found)
	end)

	it("finds a colour literal where one is written", function()
		assert.is_truthy(code('x = "0d111a"'):find(LITERALS[1].pattern))
		assert.is_truthy(code('region:SetTextColor(0.9, 0.8, 0.5)'):find(LITERALS[3].pattern))
		assert.is_falsy(code('-- "0d111a" in a comment'):find(LITERALS[1].pattern))
		assert.is_falsy(code('x = 1 -- |cffa335ee'):find(LITERALS[2].pattern))
	end)

	it("maps every Theme.HEX key onto a token", function()
		local Tokens = require("Tokens")
		local Theme = require("Theme")
		local known = {}
		local function collect(node)
			for _, value in pairs(node) do
				if type(value) == "table" then
					collect(value)
				else
					known[value] = true
				end
			end
		end
		collect(Tokens.color)
		-- The primary's pressed gold is worked out from the gold token (Theme.dimHex).
		local derived = { goldPressed = true }
		for key, hex in pairs(Theme.HEX) do
			assert.is_true(derived[key] == true or known[hex] == true, key .. " = " .. tostring(hex))
		end
	end)

	it("draws the site's colours, not the retired navy palette", function()
		local Tokens = require("Tokens")
		local Theme = require("Theme")
		assert.are.equal(Tokens.color.base.bg, Theme.HEX.background)
		assert.are.equal(Tokens.color.base.gold, Theme.HEX.gold)
		assert.are.equal(Tokens.color.base.line, Theme.HEX.border)
		assert.are.equal(Tokens.color.forever.teal, Theme.HEX.tealTop)
		assert.are.equal(Tokens.color.forever.tealEdge, Theme.HEX.tealEdge)
	end)

	it("writes rare and epic item names in the site's text colours", function()
		local Tokens = require("Tokens")
		local Theme = require("Theme")
		assert.are.equal(Tokens.color.rarity.rareText, Theme.hexOf(Theme.qualityColor(3)))
		assert.are.equal(Tokens.color.rarity.epicText, Theme.hexOf(Theme.qualityColor(4)))
		assert.are.equal(Tokens.color.rarity.uncommon, Theme.hexOf(Theme.qualityColor(2)))
		assert.are.equal(Theme.HEX.body, Theme.hexOf(Theme.qualityColor(nil)))
	end)

	it("sets text in the site's faces, shipped in media/fonts, with the client's faces as fallbacks", function()
		local Tokens = require("Tokens")
		local Theme = require("Theme")
		assert.is_truthy(Theme.TITLE_FONT:find("Marcellus%-Regular%.ttf$"))
		assert.are.equal("Fonts\\MORPHEUS.TTF", Theme.TITLE_FALLBACK)
		assert.are.equal("Fonts\\FRIZQT__.TTF", Theme.FALLBACK_FONT.path)
		for _, family in pairs(Tokens.font) do
			for _, face in pairs(family.faces) do
				local file = io.open(ROOT .. face:match("ForeverSixty\\(.*)$"):gsub("\\", "/"), "rb")
				assert.is_truthy(file, face)
				file:close()
			end
		end
	end)
end)

describe("the labels", function()
	it("are written in sentence case, never in capitals", function()
		local L = require("Locale")
		local shouting = {}
		local function walk(node, path)
			for key, value in pairs(node) do
				local name = path .. "." .. tostring(key)
				if type(value) == "table" then
					walk(value, name)
				elseif type(value) == "string" then
					-- Two capitalised words in a row ("YOUR BUILD"), or one capital word of four letters
					-- or more standing alone ("GEAR"); codes and abbreviations (FS, DPS, BiS) are short.
					local stripped = value:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
					if stripped:find("%f[%a]%u%u+%s+%u%u+%f[%A]") or stripped:find("^%u%u%u%u+$") then
						shouting[#shouting + 1] = name .. " = " .. value
					end
				end
			end
		end
		walk(L, "L")
		table.sort(shouting)
		assert.are.same({}, shouting)
	end)
end)
